{
  "technical_and_design_decisions": [
    "Use Spring Boot 3.x (Java 17+ baseline) as the foundation for the new Boot-based ModuleRunner (U4), replacing the legacy xd-container runtime.",
    "Reuse the existing gpfdist sink module by extracting the protocol-handling layer into a reusable gpfdist-writer component that can be consumed by a batch job (U6).",
    "Add three new REST endpoints following the existing Spring MVC controller patterns and conventions for the metrics module; introduce a bulk-retrieval service method that delegates to the existing per-name metric repositories to avoid duplication (U3).",
    "Externalize the Sqoop metastore configuration through a new property (e.g., 'sqoop.metastore.config') backed by Spring property placeholders, preserving the default behavior for backward compatibility (U1).",
    "Leverage Spring Security abstractions and GemFire's native security APIs to implement authentication/authorization for the GemFire source module; expose properties for credentials and security configuration (U5).",
    "Restructure the test infrastructure to separate 'mock-only' test slices from 'real-repository' integration tests using Spring's @TestConfiguration, profile-based bean loading, and dedicated test source sets (U7).",
    "Move the reactor-based data processor module from the spring-xd-modules repository into the core, adding it as a default module and removing the external dependency for processor authors (U8).",
    "Maintain backward compatibility with existing module definitions, batch jobs, and REST clients throughout all changes.",
    "Update reference documentation (AsciiDoc) and configuration metadata for every user-visible change."
  ],
  "assumptions": [
    "A single senior Java/Spring developer familiar with the Spring XD codebase is performing all the work; no onboarding ramp-up time is included.",
    "The Spring XD codebase, build system (Gradle), and CI pipeline are already in place and do not require new infrastructure setup.",
    "Target runtime is Java 17 or later (consistent with Spring Framework 6.0 / Spring Boot 3.x requirements).",
    "External systems referenced in the user stories (Sqoop, HDFS, GemFire, HAWQ/GPDB, gpfdist) are available in development/test environments; effort for provisioning them is not included.",
    "For U4 ('Scope: *'), the scope is interpreted as applying to the entire increment (i.e., U4 is a major architectural change that affects the overall delivery, not that all other user stories are out of scope).",
    "Documentation uses the existing AsciiDoc format already present in the project; no new documentation tooling is required.",
    "Bug fixing is estimated as a separate cross-cutting activity (approximately 10% of development effort) and is not double-counted in individual user stories.",
    "Existing tests are green at the start of the increment; effort for fixing pre-existing failures is not included.",
    "Effort estimates represent productive development hours (coding, testing, reviewing, documenting) and exclude meetings, administrative overhead, and waiting time."
  ],
  "activities": [
    {
      "activity_id": "A0",
      "activity_name": "Architecture and Design Review",
      "activity_description": "Cross-cutting architecture and design work: review the existing module runner, metrics service, and test infrastructure; design the Boot-based ModuleRunner abstraction, plan the gpfdist-writer extraction, and document cross-cutting design decisions."
    },
    {
      "activity_id": "A1",
      "activity_name": "U1 - Configurable Sqoop Metastore",
      "activity_description": "Externalize the Sqoop metastore configuration, add a new configurable property, update the Sqoop module to read it, add unit and integration tests, and update the reference documentation."
    },
    {
      "activity_id": "A2",
      "activity_name": "U2 - HDFS Module Registry Documentation",
      "activity_description": "Update the reference documentation (XD-2287) to describe how to configure an HDFS-backed module registry, including required properties, deployment topology, and operational caveats."
    },
    {
      "activity_id": "A3",
      "activity_name": "U3 - Bulk Metrics REST API",
      "activity_description": "Implement three new REST endpoints (/metrics/counters/all, /metrics/gauges/all, /metrics/rich-gauges/all). Add bulk-retrieval methods to the metrics service, add controller endpoints, write unit and integration tests, and update the REST API documentation."
    },
    {
      "activity_id": "A4",
      "activity_name": "U4 - Boot-based ModuleRunner (main scope)",
      "activity_description": "Implement a Spring Boot-based ModuleRunner that allows running XD without xd-containers. Design the new bootstrap and lifecycle, port container-managed module execution to a Boot application, update configuration and auto-configuration, ensure existing modules still run, write comprehensive tests, and document the new deployment mode."
    },
    {
      "activity_id": "A5",
      "activity_name": "U5 - GemFire Source with Native Authentication",
      "activity_description": "Research GemFire native security, add authentication/authorization support to the GemFire source module, expose the relevant security properties, add tests, and document where the GF-specific native and security properties must be configured."
    },
    {
      "activity_id": "A6",
      "activity_name": "U6 - jdbcgpfdist Batch Job",
      "activity_description": "Build an out-of-the-box jdbcgpfdist batch job that reads from JDBC and writes to HAWQ/GPDB using the gpfdist protocol. Refactor the existing gpfdist sink to expose a reusable writer, implement the JDBC reader, wire the batch job together, add tests, and document the new job."
    },
    {
      "activity_id": "A7",
      "activity_name": "U7 - Test Infrastructure Refactoring",
      "activity_description": "Refactor the test infrastructure to clearly separate mock-based unit tests from real-repository integration tests. Introduce profile/test-slice based configuration, update existing tests to use the new structure, and document the testing conventions."
    },
    {
      "activity_id": "A8",
      "activity_name": "U8 - Reactor Data Processor Module to Core",
      "activity_description": "Move the reactor-based data processor module from the spring-xd-modules repository into the core repository, update build/dependency configuration, ensure Reactor's Stream API is usable for processor modules out of the box, update tests, and document the new core module."
    },
    {
      "activity_id": "A9",
      "activity_name": "Integration Testing",
      "activity_description": "Run end-to-end integration tests across all user stories, validate backward compatibility, verify the new Boot-based ModuleRunner runs representative modules, and validate the bulk metrics endpoints and the jdbcgpfdist batch job against representative environments."
    },
    {
      "activity_id": "A10",
      "activity_name": "Documentation and Release Notes",
      "activity_description": "Update reference documentation, configuration guides, and release notes for all user-visible changes (U1-U8). Includes updating the GF security configuration guide, the metrics API guide, the module registry guide, and the migration notes for the new ModuleRunner."
    },
    {
      "activity_id": "A11",
      "activity_name": "Code Review and Bug Fixing",
      "activity_description": "Cross-cutting code review, addressing review feedback, fixing defects discovered during testing and integration, and final stabilization of the increment."
    }
  ],
  "activities_estimates_only": [
    {"activity_id": "A0", "most_likely_effort": 12},
    {"activity_id": "A1", "most_likely_effort": 16},
    {"activity_id": "A2", "most_likely_effort": 6},
    {"activity_id": "A3", "most_likely_effort": 28},
    {"activity_id": "A4", "most_likely_effort": 96},
    {"activity_id": "A5", "most_likely_effort": 24},
    {"activity_id": "A6", "most_likely_effort": 56},
    {"activity_id": "A7", "most_likely_effort": 32},
    {"activity_id": "A8", "most_likely_effort": 18},
    {"activity_id": "A9", "most_likely_effort": 16},
    {"activity_id": "A10", "most_likely_effort": 8},
    {"activity_id": "A11", "most_likely_effort": 16}
  ],
  "reported_total": {
    "most_likely_effort": 328
  }
}
